INSERT INTO companies (id, name, short, initials, color, logo, phone, about, size, founded, rating, reviews, mst, license, verified, verify_status, created_at) VALUES ('long-hai', 'Công ty CP Dịch vụ Bảo vệ Long Hải', 'Long Hải', 'LH', '#1f2a6b', '/assets/img/logos/long-hai.png', '0909 123 456', 'Long Hải là đơn vị bảo vệ chuyên nghiệp hơn 15 năm, phục vụ hơn 300 mục tiêu tòa nhà văn phòng, chung cư cao cấp và trung tâm thương mại tại TP.HCM và các tỉnh lân cận. Cam kết trả lương đúng hạn ngày 5 hàng tháng, đóng BHXH đầy đủ, không thu bất kỳ khoản phí nào của người lao động.', '1.200+ nhân viên', 2009, 4.7, 182, '0312 456 789', 'GPKD ANTT số 245/GXN-PC06', 1, 'done', 1795316353663);
INSERT INTO companies (id, name, short, initials, color, logo, phone, about, size, founded, rating, reviews, mst, license, verified, verify_status, created_at) VALUES ('an-phat', 'Công ty Dịch vụ Bảo vệ An Quốc', 'An Quốc', 'AQ', '#7a5a12', '/assets/img/logos/an-phat.png', '0912 345 678', 'An Quốc cung cấp dịch vụ vệ sĩ, bảo vệ ngân hàng, áp tải tiền và bảo vệ sự kiện tại miền Bắc. Đội ngũ được đào tạo bài bản về võ thuật, PCCC và sơ cấp cứu.', '800+ nhân viên', 2012, 4.5, 96, '0108 765 432', 'GPKD ANTT số 118/GXN-PC06', 1, 'done', 1795316353663);
INSERT INTO companies (id, name, short, initials, color, logo, phone, about, size, founded, rating, reviews, mst, license, verified, verify_status, created_at) VALUES ('phuong-nam', 'Công ty CP Dịch vụ Bảo vệ Phương Nam', 'Phương Nam', 'PN', '#0f6b4f', '/assets/img/logos/phuong-nam.png', '0938 222 333', 'Chuyên bảo vệ nhà máy, kho bãi tại các KCN Bình Dương, Đồng Nai. Có ký túc xá miễn phí, bếp ăn tập thể và xe đưa đón cho nhân viên.', '2.000+ nhân viên', 2007, 4.6, 241, '3702 111 222', 'GPKD ANTT số 77/GXN-PC06', 1, 'done', 1795316353663);
INSERT INTO companies (id, name, short, initials, color, logo, phone, about, size, founded, rating, reviews, mst, license, verified, verify_status, created_at) VALUES ('thang-long', 'Công ty TNHH MTV DV Bảo vệ Thăng Long', 'Thăng Long', 'TL', '#8b1e2d', '/assets/img/logos/thang-long.webp', '0983 456 111', 'Thăng Long phục vụ các tòa nhà văn phòng, bệnh viện và trường học tại Hà Nội, Bắc Ninh với chế độ đãi ngộ ổn định.', '600+ nhân viên', 2014, 4.3, 58, '0105 999 001', 'GPKD ANTT số 302/GXN-PC06', 1, 'done', 1795316353663);
INSERT INTO companies (id, name, short, initials, color, logo, phone, about, size, founded, rating, reviews, mst, license, verified, verify_status, created_at) VALUES ('sao-viet', 'Công ty TNHH An ninh Sao Việt', 'Sao Việt', 'SV', '#2d4a8a', NULL, '0977 888 999', 'Đơn vị bảo vệ trẻ, chuyên bảo vệ sự kiện, triển lãm và cửa hàng bán lẻ.', '150+ nhân viên', 2020, 4, 12, '0316 222 888', 'Đang chờ xác thực', 0, 'none', 1795316353663);
INSERT INTO companies (id, name, short, initials, color, logo, phone, about, size, founded, rating, reviews, mst, license, verified, verify_status, created_at) VALUES ('hai-au', 'Công ty CP Vệ sĩ SOS', 'Vệ sĩ SOS', 'SOS', '#0b6b8a', '/assets/img/logos/hai-au.png', '0905 666 777', 'Bảo vệ resort, khách sạn và chung cư ven biển Đà Nẵng. Môi trường làm việc chuyên nghiệp, thưởng lễ Tết đầy đủ.', '400+ nhân viên', 2011, 4.4, 44, '0401 555 666', 'GPKD ANTT số 56/GXN-PC06', 1, 'done', 1795316353663);
